import { DEFAULT_AVATAR_URL, DEFAULT_PROFILE_NAME } from '../config';

const STORAGE_KEY = 'review-profile-local-v1';

const DEFAULT_REVIEW_PROFILE = {
	id: 'review_current_user',
	nickname: DEFAULT_PROFILE_NAME || '社区访客',
	avatarUrl: DEFAULT_AVATAR_URL,
	intro: '记录生活，分享此刻'
};

export function getReviewProfile() {
	try {
		const profile = uni.getStorageSync(STORAGE_KEY);
		return profile && typeof profile === 'object'
			? { ...DEFAULT_REVIEW_PROFILE, ...profile }
			: { ...DEFAULT_REVIEW_PROFILE };
	} catch (error) {
		return { ...DEFAULT_REVIEW_PROFILE };
	}
}

export function updateReviewProfile(updates = {}) {
	const profile = { ...getReviewProfile(), ...updates, id: 'review_current_user' };
	try {
		uni.setStorageSync(STORAGE_KEY, profile);
	} catch (error) {}
	return profile;
}
